from collections import Counter, deque

def transform(grid):
    g=[r[:] for r in grid]; H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    obj=[c for c,_ in cnt.most_common() if c!=bg][0]
    rs=[r for r in range(H) for c in range(W) if g[r][c]==obj]
    cs=[c for r in range(H) for c in range(W) if g[r][c]==obj]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    out=[r[:] for r in g]
    # bbox border gaps
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if g[r][c]==bg: out[r][c]=2
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if g[r][c]==bg: out[r][c]=2
    # interior vertical sandwiches: bg cell with obj somewhere above and below in same col, not on bbox border cols
    for c in range(c0+1,c1):
        col=[g[r][c] for r in range(H)]
        for r in range(r0+1,r1):
            if g[r][c]==bg:
                above=any(col[k]==obj for k in range(0,r))
                below=any(col[k]==obj for k in range(r+1,H))
                if above and below: out[r][c]=2
    return out

